import java.util.*;

class Solution {
    public boolean hasPairWithSum(int[] nums, int target) {
        HashSet<Integer> seen = new HashSet<>();
        for (int x : nums) {
            if (seen.contains(target - x)) { // partner seen at an earlier position
                return true;
            }
            seen.add(x);
        }
        return false;
    }
}

