function hasPairWithSum(nums, target) {
  const a = [...nums].sort((x, y) => x - y); let i = 0, j = a.length - 1;
  while (i < j) { const s = a[i] + a[j]; if (s === target) return true; if (s < target) i++; else j--; }
  return false;
}
